def find_user(self, username):
        """Load a user row by username, or None."""
        row = self.conn.execute(
            "SELECT username, salt, password_hash FROM users WHERE username = ?", (username,)
        ).fetchone()
        if row is None:
            return None
        return {"username": row[0], "salt": row[1], "password_hash": row[2]}

def with_retries(operation):
    """Run a database operation, retrying up to MAX_RETRIES times with linear backoff."""
    last_error = None
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            return operation()
        except sqlite3.OperationalError as exc:
            last_error = exc
            time.sleep(RETRY_BACKOFF_SECONDS * attempt)
    raise DatabaseError(f"operation failed after {MAX_RETRIES} retries: {last_error}")

